[20010001] ="return {type_id = 20010001,goods_name = [[ 神兵绽放魔晶 ]],intro = [[ 每颗魔晶可提升<fontcolor='#0a953e'>100点暴击</font><br/>前往<fontcolor='#0a953e'>神兵界面</font>使用提升神兵属性 ]],getway = [[ 魔晶产自异界通道附近的黑塔之内，层数越高，魔晶越高级。异界通道是由龙族离开奇幻大陆时创造于奇幻大陆与奇幻大陆之外世界的单行道。 ]],getway_url = [[ [{10000,0}] ]],bind = 0,trade = 0,if_custom_price = 0,sell = 0,type = 20,subtype = 1,sell_category = 1,sell_subcategory = 0,equip_type = 0,goods_icon = 20010001,career_id = 0,level = 0,max_overlap = 99999,color = 3,expire_time = 0,trade_price = [[ [] ]],lock_time = 0,use = 0,compose = 0,quick_use = 0,use_one_key = 0,base_attrlist = [[ [] ]],addition = [[ [] ]],skill = [[ [] ]],model_id = 0,sex = 0,turn = 0,jump = 1,bag_location = 4,effect_id = 0,source = [[  ]],expire_type = 0,can_storge = 1}",
[20010002] ="return {type_id = 20010002,goods_name = [[ 神兵秩序魔晶 ]],intro = [[ 每颗魔晶可提升<fontcolor='#0a953e'>100点攻击</font><br/>前往<fontcolor='#0a953e'>神兵界面</font>使用提升神兵属性 ]],getway = [[ 奇幻大陆上没有生灵知道异界通道的对面的世界是什么样子，即使有好奇心也被时间和巨大的代价渐渐消磨。但日子并没有一直平静—— ]],getway_url = [[ [{10000,0}] ]],bind = 0,trade = 0,if_custom_price = 0,sell = 0,type = 20,subtype = 1,sell_category = 1,sell_subcategory = 0,equip_type = 0,goods_icon = 20010002,career_id = 0,level = 0,max_overlap = 99999,color = 4,expire_time = 0,trade_price = [[ [] ]],lock_time = 0,use = 0,compose = 0,quick_use = 0,use_one_key = 0,base_attrlist = [[ [] ]],addition = [[ [] ]],skill = [[ [] ]],model_id = 0,sex = 0,turn = 0,jump = 1,bag_location = 4,effect_id = 1004,source = [[  ]],expire_type = 0,can_storge = 1}",
