[22030011] ="return {type_id = 22030011,goods_name = [[ 梵音圣使碎片 ]],intro = [[ 可用于激活或进阶契灵<fontcolor='#0a953e'>【梵音圣使】</font><br/>激活后可获得契灵技能<br/><fontcolor='#a376ff'>悟世真言:为角色和队友增加20%攻击,持续5秒</font><br/>培养至3阶<br/><fontcolor='#0a953e'>永久提升角色</font><fontcolor='#ff9015'>攻击加成1%</font>,<fontcolor='#0a953e'>悟世真言额外恢复10%最大生命值</font><br/>培养至6阶<br/><fontcolor='#0a953e'>永久提升角色</font><fontcolor='#ff9015'>攻击加成2%</font>,<fontcolor='#0a953e'>悟世真言额外提供5%吸血</font><br/>培养至8阶<br/><fontcolor='#0a953e'>永久提升角色</font><fontcolor='#ff9015'>暴击几率2%</font>,<fontcolor='#0a953e'>悟世真言额外提供速度加成50%</font><br/>激活属性加成:<br/> ]],getway = [[ “一切有为法。如梦幻泡影。如露亦如电。应作如是观。”通过数十年如一日的苦行和艰深难懂的真言，他是否终于得以窥见当世的真理呢？ ]],getway_url = [[ [{10000,0}] ]],bind = 0,trade = 0,if_custom_price = 0,sell = 0,type = 22,subtype = 3,sell_category = 0,sell_subcategory = 0,equip_type = 0,goods_icon = 22030011,career_id = 0,level = 0,max_overlap = 99999,color = 7,expire_time = 0,trade_price = [[ [] ]],lock_time = 0,use = 1,compose = 0,quick_use = 0,use_one_key = 0,base_attrlist = [[ [{1,4000},{2,80000},{3,2000},{4,2000}] ]],addition = [[ [] ]],skill = [[ [] ]],model_id = 0,sex = 0,turn = 0,jump = 1,bag_location = 4,effect_id = 1006,source = [[  ]],expire_type = 0,can_storge = 1}",
